arguments.command:
# The addresses are likely in .data or .rodata - let's check all sections
aarch64-linux-gnu-readelf -SW /tmp/symbols/libmonosgen-2.0.so.dbg 2>/dev/null | head -40

# Also look at dynamic symbols near those addresses
aarch64-linux-gnu-readelf -sW /tmp/symbols/libmonosgen-2.0.so.debug 2>/dev/null | awk '/FUNC/{addr=strtonum("0x"$2); if(addr<=0x2f4c84 && addr>=0x2f4000) print}' | head -10

# Check what section 0x2f4b20 falls in
aarch64-linux-gnu-readelf -SW /tmp/symbols/libmonosgen-2.0.so.dbg 2>/dev/null | awk '{
  if(NF>6 && $2 ~ /^\./) {
    addr=strtonum($4); size=strtonum($6);
    if(0x2f4b20 >= addr && 0x2f4b20 < addr+size) print "0x2f4b20 is in "$2" (addr="$4" size="$6")"
  }
}'

