# Find what data objects contain those addresses
aarch64-linux-gnu-readelf -sW /tmp/symbols/libmonosgen-2.0.so.debug 2>/dev/null | awk '/OBJECT/{
  addr=strtonum("0x"$2); size=strtonum("0x"$3);
  if(addr <= 0x2f4b20 && addr+size > 0x2f4b20) print "0x2f4b20 in " $NF " at " $2 " size " $3
  if(addr <= 0x2f4c84 && addr+size > 0x2f4c84) print "0x2f4c84 in " $NF " at " $2 " size " $3
